import Darwin
import Foundation

import BridgeCore

/// One allowlisted status event. Every field is either an enum raw value from
/// the shared lifecycle, a boolean, a count, a generation, a port or a
/// timestamp generated by the host. No caller supplies free-form text, so
/// client names/ids/addresses, keys, tokens, requested text, AX content,
/// screenshot bytes and raw log bodies cannot enter the log by construction.
struct BridgeProductStatusEvent: Codable, Equatable, Sendable {
    enum Kind: String, Codable, Sendable {
        case launch
        case ownerStart
        case ownerResume
        case ownerStop
        case authenticatedStop
        case remoteStop
        case autoRestore
        case sharedState
        case rpcState
        case serviceClosed
        case lanPreference
        case bonjourPreference
        case pairingDecision
        case pairingWithdrawn
        case clientRevoked
        case allClientsRevoked
        case sensitiveInputChanged
    }

    var sequence: UInt64
    var at: String
    var kind: Kind
    var phase: String?
    var tunnel: String?
    var ddi: String?
    var ddiSource: String?
    var ddiLayout: String?
    var ddiMethod: String?
    var ddiStage: String?
    var ddiOutcome: String?
    var ddiElapsedMilliseconds: Int?
    var lastOnDeviceMountAt: String?
    var lastOnDeviceMountLayout: String?
    var engineEntryObserved: Bool?
    var engineRunning: Bool?
    var serviceRunning: Bool?
    var terminalFault: Bool?
    var oneShotDispatched: Bool?
    var pairingImported: Bool?
    var generation: UInt64?
    var rpcRunning: Bool?
    var loopbackReady: Bool?
    var lanEnabled: Bool?
    var lanReady: Bool?
    var bonjour: String?
    var engineReady: Bool?
    var engineGeneration: UInt64?
    var port: UInt16?
    var clientCount: Int?
    var methodCount: Int?
    var capabilityCount: Int?
    var lanPreference: Bool?
    var bonjourPreference: Bool?
    var allowed: Bool?
    var granted: Bool?
    var succeeded: Bool?

    enum CodingKeys: String, CodingKey {
        case sequence = "s"
        case at = "t"
        case kind = "k"
        case phase = "p"
        case tunnel = "u"
        case ddi = "d"
        case ddiSource = "ds"
        case ddiLayout = "dl"
        case ddiMethod = "dm"
        case ddiStage = "dst"
        case ddiOutcome = "do"
        case ddiElapsedMilliseconds = "de"
        case lastOnDeviceMountAt = "la"
        case lastOnDeviceMountLayout = "ll"
        case engineEntryObserved = "e"
        case engineRunning = "r"
        case serviceRunning = "v"
        case terminalFault = "f"
        case oneShotDispatched = "n"
        case pairingImported = "i"
        case generation = "g"
        case rpcRunning = "q"
        case loopbackReady = "l"
        case lanEnabled = "a"
        case lanReady = "b"
        case bonjour = "j"
        case engineReady = "y"
        case engineGeneration = "eg"
        case port = "o"
        case clientCount = "c"
        case methodCount = "m"
        case capabilityCount = "x"
        case lanPreference = "lp"
        case bonjourPreference = "bp"
        case allowed = "ok"
        case granted = "gr"
        case succeeded = "su"
    }

    /// Deterministic one-line projection used by `recentLog`, the owner
    /// disclosure and the authenticated `/logs` byte channel.
    func formattedLine() -> String {
        var fields = ["t=\(at)", "s=\(sequence)", "k=\(kind.rawValue)"]
        if let phase { fields.append("phase=\(phase)") }
        if let tunnel { fields.append("tunnel=\(tunnel)") }
        if let ddi { fields.append("ddi=\(ddi)") }
        if let ddiSource { fields.append("ddi_source=\(ddiSource)") }
        if let ddiLayout { fields.append("ddi_layout=\(ddiLayout)") }
        if let ddiMethod { fields.append("ddi_method=\(ddiMethod)") }
        if let ddiStage { fields.append("ddi_stage=\(ddiStage)") }
        if let ddiOutcome { fields.append("ddi_outcome=\(ddiOutcome)") }
        if let ddiElapsedMilliseconds { fields.append("ddi_elapsed_ms=\(ddiElapsedMilliseconds)") }
        if let lastOnDeviceMountAt { fields.append("last_ondevice_mount=\(lastOnDeviceMountAt)") }
        if let lastOnDeviceMountLayout { fields.append("last_ondevice_layout=\(lastOnDeviceMountLayout)") }
        if let engineEntryObserved { fields.append("entry=\(engineEntryObserved)") }
        if let engineRunning { fields.append("engine=\(engineRunning)") }
        if let serviceRunning { fields.append("service=\(serviceRunning)") }
        if let terminalFault { fields.append("terminal=\(terminalFault)") }
        if let oneShotDispatched { fields.append("dispatched=\(oneShotDispatched)") }
        if let pairingImported { fields.append("pairing=\(pairingImported)") }
        if let generation { fields.append("generation=\(generation)") }
        if let rpcRunning { fields.append("rpc=\(rpcRunning)") }
        if let loopbackReady { fields.append("loopback=\(loopbackReady)") }
        if let lanEnabled { fields.append("lan=\(lanEnabled)") }
        if let lanReady { fields.append("lan_ready=\(lanReady)") }
        if let bonjour { fields.append("bonjour=\(bonjour)") }
        if let engineReady { fields.append("engine_ready=\(engineReady)") }
        if let engineGeneration { fields.append("engine_generation=\(engineGeneration)") }
        if let port { fields.append("port=\(port)") }
        if let clientCount { fields.append("clients=\(clientCount)") }
        if let methodCount { fields.append("methods=\(methodCount)") }
        if let capabilityCount { fields.append("capabilities=\(capabilityCount)") }
        if let lanPreference { fields.append("lan_pref=\(lanPreference)") }
        if let bonjourPreference { fields.append("bonjour_pref=\(bonjourPreference)") }
        if let allowed { fields.append("allowed=\(allowed)") }
        if let granted { fields.append("granted=\(granted)") }
        if let succeeded { fields.append("ok=\(succeeded)") }
        return fields.joined(separator: " ")
    }
}

/// Fixed health projection for the Diagnostics surface and safe export.
/// `persistence` is "persistent" while the App-private directory is usable and
/// the latest staging/rename flush (if one has run) succeeded; a failed write
/// is reported as "memory-only" and never blocks automation or claims durable
/// storage.
struct BridgeProductStatusLogHealth: Codable, Equatable, Sendable {
    var eventCount: Int
    var retainedDates: [String]
    var persistence: String
    var lastFailure: String?

    static let unavailable = BridgeProductStatusLogHealth(
        eventCount: 0,
        retainedDates: [],
        persistence: "memory-only",
        lastFailure: "not-started"
    )
}

/// Bounded, privacy-constrained status-event source for the canonical RPC
/// log routes. It observes typed state transitions only; it never wraps,
/// copies or reads `BridgeLog`, engine logs or request payloads.
///
/// Persistence is a current JSONL file plus one bounded rotation under the
/// App-private Application Support directory. Each flush writes the complete
/// bounded current/rotation snapshots to a 0600 staging file and renames it
/// into place on one serial queue, so the main actor never waits for fsync.
/// A failed write leaves the in-memory events readable for this session and
/// marks persistence unavailable; it never throws into a caller.
final class BridgeProductStatusLog: BridgeRPCLogSource, @unchecked Sendable {
    static let currentFileName = "status-events.jsonl"
    static let rotatedFileName = "status-events.1.jsonl"
    static let defaultMaxEvents = 512
    static let defaultMaxBytes = 128 * 1_024

    private let lock = NSLock()
    private let writeQueue: DispatchQueue
    private let directory: URL
    private let ddiProgressURL: URL
    private let restoredStatusURL: URL
    private let maxEvents: Int
    private let maxBytes: Int
    private let now: @Sendable () -> Date

    private var events: [BridgeProductStatusEvent] = []
    private var current: [BridgeProductStatusEvent] = []
    private var rotated: [BridgeProductStatusEvent] = []
    private var sequence: UInt64 = 0
    private var persistenceAvailable = false
    private var lastFailure: String?
    /// Last verified on-device mount facts restored from the previous
    /// process's app-private status.json. They are historical evidence only;
    /// they never become a current `ddi_source` claim.
    private var restoredLastOnDeviceMountAt: String?
    private var restoredLastOnDeviceMountLayout: String?

    init(directory: URL? = nil,
         ddiProgressURL: URL? = nil,
         statusURL: URL? = nil,
         maxEvents: Int = defaultMaxEvents,
         maxBytes: Int = defaultMaxBytes,
         now: @escaping @Sendable () -> Date = { Date() }) {
        self.directory = directory ?? BridgePaths.supportDirectory
            .appendingPathComponent("StatusLog", isDirectory: true)
        self.ddiProgressURL = ddiProgressURL ?? BridgePaths.ddiInstallProgressFile
        self.restoredStatusURL = statusURL ?? BridgePaths.statusFile
        self.maxEvents = max(16, maxEvents)
        self.maxBytes = max(1_024, maxBytes)
        self.now = now
        self.writeQueue = DispatchQueue(
            label: "org.floeagent.iosbridge.product.status-log",
            qos: .utility
        )
        prepareDirectory()
        loadRetainedEvents()
        loadRestoredMountFacts()
    }

    /// Records one actual state transition or explicit owner action. The
    /// caller supplies typed snapshots and fixed flags only.
    func record(kind: BridgeProductStatusEvent.Kind,
                shared: BridgeSnapshot,
                rpc: BridgeRPCHostSnapshot,
                ddiMethod: String? = nil,
                lanPreference: Bool? = nil,
                bonjourPreference: Bool? = nil,
                allowed: Bool? = nil,
                granted: Bool? = nil,
                succeeded: Bool? = nil) {
        let date = now()
        let ddiProgress = Self.currentDDIProgressFacts(url: ddiProgressURL)
        let sharedMountAt = Self.safeTimestamp(shared.lastOnDeviceMountAt)
        let lastMountAt = sharedMountAt ?? restoredLastOnDeviceMountAt
        var event = BridgeProductStatusEvent(
            sequence: 0,
            at: BridgeClock.timestamp(date),
            kind: kind,
            phase: shared.phase.rawValue,
            tunnel: shared.tunnel.rawValue,
            ddi: shared.ddi.rawValue,
            ddiSource: Self.ddiSourceValue(shared.ddiSource),
            ddiLayout: Self.ddiLayoutValue(shared.ddiLayout),
            ddiMethod: Self.ddiMethodValue(ddiMethod),
            ddiStage: ddiProgress.stage,
            ddiOutcome: ddiProgress.outcome,
            ddiElapsedMilliseconds: ddiProgress.elapsedMilliseconds,
            lastOnDeviceMountAt: lastMountAt,
            lastOnDeviceMountLayout: lastMountAt == nil
                ? nil
                : (sharedMountAt == nil
                    ? restoredLastOnDeviceMountLayout
                    : Self.ddiLayoutValue(shared.lastOnDeviceMountLayout)),
            engineEntryObserved: shared.engineEntryObserved,
            engineRunning: shared.engineRunning,
            serviceRunning: shared.serviceRunning,
            terminalFault: shared.terminalFault,
            oneShotDispatched: shared.oneShotDispatched,
            pairingImported: shared.pairingImported,
            generation: shared.generation,
            rpcRunning: rpc.running,
            loopbackReady: rpc.loopbackReady,
            lanEnabled: rpc.lanEnabled,
            lanReady: rpc.lanReady,
            bonjour: Self.bonjourValue(rpc.bonjourState),
            engineReady: rpc.engine.readiness.isReady,
            engineGeneration: rpc.engine.generation,
            port: rpc.port,
            clientCount: rpc.clients.count,
            methodCount: rpc.engine.supportedMethods.count,
            capabilityCount: rpc.capabilities.count,
            lanPreference: lanPreference,
            bonjourPreference: bonjourPreference,
            allowed: allowed,
            granted: granted,
            succeeded: succeeded
        )

        lock.lock()
        sequence &+= 1
        event.sequence = sequence
        events.append(event)
        trimRAMLocked()
        appendToFilesLocked(event)
        let currentSnapshot = current
        let rotatedSnapshot = rotated
        lock.unlock()

        writeQueue.async { [weak self] in
            self?.flush(current: currentSnapshot, rotated: rotatedSnapshot)
        }
    }

    // MARK: - BridgeRPCLogSource

    func recentLog(limit: Int, matching: String?) -> [String] {
        let bounded = min(max(limit, 1), 500)
        let filter = matching?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        lock.lock()
        let retained = events
        lock.unlock()

        var lines: [String] = []
        for event in retained.reversed() {
            let line = event.formattedLine()
            if let filter, !filter.isEmpty, !line.lowercased().contains(filter) {
                continue
            }
            lines.append(line)
            if lines.count >= bounded { break }
        }
        return lines.reversed()
    }

    func logFiles() -> [String]? {
        lock.lock()
        let available = persistenceAvailable
        lock.unlock()
        guard available else { return nil }
        var names: [String] = []
        if FileManager.default.fileExists(atPath: currentURL.path) {
            names.append(Self.currentFileName)
        }
        if FileManager.default.fileExists(atPath: rotatedURL.path) {
            names.append(Self.rotatedFileName)
        }
        return names.isEmpty ? nil : names
    }

    func logHistory(date: String?) -> String? {
        lock.lock()
        var retained = rotated + current
        if retained.isEmpty {
            retained = events
        }
        lock.unlock()
        var seen = Set<UInt64>()
        let ordered = retained
            .filter { seen.insert($0.sequence).inserted }
            .sorted { $0.sequence < $1.sequence }
            .suffix(maxEvents)
        guard !ordered.isEmpty else { return nil }
        if let date {
            let prefix = date + "T"
            let lines = ordered
                .filter { $0.at.hasPrefix(prefix) }
                .map { $0.formattedLine() }
            return lines.isEmpty ? nil : lines.joined(separator: "\n")
        }
        var dates = Set<String>()
        for event in ordered where event.at.count >= 10 {
            dates.insert(String(event.at.prefix(10)))
        }
        guard !dates.isEmpty else { return nil }
        return dates.sorted().joined(separator: "\n")
    }

    // MARK: - Health / testing

    func health() -> BridgeProductStatusLogHealth {
        lock.lock()
        defer { lock.unlock() }
        return BridgeProductStatusLogHealth(
            eventCount: events.count,
            retainedDates: retainedDatesLocked(),
            persistence: persistenceAvailable ? "persistent" : "memory-only",
            lastFailure: lastFailure
        )
    }

    /// Test seam: wait for queued flushes without exposing the private queue.
    func flushForTesting() {
        writeQueue.sync {}
    }

    /// Only status dimensions that the event actually records count as an RPC
    /// change. Client `lastActiveAt`/address churn from ordinary requests does
    /// not produce a status event or a disk write.
    static func rpcChanged(previous: BridgeRPCHostSnapshot,
                           current: BridgeRPCHostSnapshot) -> Bool {
        previous.running != current.running ||
            previous.loopbackIPv4Ready != current.loopbackIPv4Ready ||
            previous.loopbackIPv6Ready != current.loopbackIPv6Ready ||
            previous.lanIPv4Ready != current.lanIPv4Ready ||
            previous.lanIPv6Ready != current.lanIPv6Ready ||
            previous.lanEnabled != current.lanEnabled ||
            bonjourValue(previous.bonjourState) != bonjourValue(current.bonjourState) ||
            previous.port != current.port ||
            previous.engine.readiness.isReady != current.engine.readiness.isReady ||
            previous.engine.generation != current.engine.generation ||
            previous.engine.supportedMethods.count != current.engine.supportedMethods.count ||
            previous.clients.count != current.clients.count ||
            previous.capabilities.count != current.capabilities.count ||
            (previous.storageError == nil) != (current.storageError == nil) ||
            previous.nonceStoreAvailable != current.nonceStoreAvailable ||
            (previous.networkError == nil) != (current.networkError == nil)
    }

    /// A shared-state change is logged only when one of the allowlisted
    /// lifecycle dimensions actually changed. The 1 Hz refresh timer does not
    /// write an unchanged status.
    static func sharedChanged(previous: BridgeSnapshot,
                              current: BridgeSnapshot) -> Bool {
        previous.phase != current.phase ||
            previous.tunnel != current.tunnel ||
            previous.ddi != current.ddi ||
            previous.ddiSource != current.ddiSource ||
            previous.ddiLayout != current.ddiLayout ||
            previous.lastOnDeviceMountAt != current.lastOnDeviceMountAt ||
            previous.lastOnDeviceMountLayout != current.lastOnDeviceMountLayout ||
            previous.engineEntryObserved != current.engineEntryObserved ||
            previous.engineRunning != current.engineRunning ||
            previous.serviceRunning != current.serviceRunning ||
            previous.terminalFault != current.terminalFault ||
            previous.oneShotDispatched != current.oneShotDispatched ||
            previous.pairingImported != current.pairingImported ||
            previous.generation != current.generation
    }

    // MARK: - Private

    private struct DDIProgressFacts {
        var stage: String?
        var outcome: String?
        var elapsedMilliseconds: Int?
    }

    /// Reads only the typed install-progress fields, and only when the record
    /// belongs to this process. The path, error code, notes and any other free
    /// text are never copied into the status event.
    private static func currentDDIProgressFacts(url: URL) -> DDIProgressFacts {
        guard let object = BridgeAtomicFile.readJSON(url),
              let hostPid = object["hostPid"] as? Int,
              hostPid == Int(ProcessInfo.processInfo.processIdentifier),
              let stageRaw = object["stage"] as? String,
              let stage = BridgeDDIInstallStage(rawValue: stageRaw),
              let outcomeRaw = object["outcome"] as? String,
              let outcome = BridgeDDIInstallOutcome(rawValue: outcomeRaw) else {
            return DDIProgressFacts()
        }
        let elapsed = object["elapsedMilliseconds"] as? Int
        let boundedElapsed = elapsed.flatMap {
            (0...86_400_000).contains($0) ? $0 : nil
        }
        return DDIProgressFacts(
            stage: stage.rawValue,
            outcome: outcome.rawValue,
            elapsedMilliseconds: boundedElapsed
        )
    }

    private static func ddiSourceValue(_ raw: String?) -> String {
        if raw == BridgeDDIMountProvenance.onDevice.rawValue {
            return BridgeDDIMountProvenance.onDevice.rawValue
        }
        if raw == BridgeDDIMountProvenance.preexisting.rawValue {
            return BridgeDDIMountProvenance.preexisting.rawValue
        }
        // No recognized native provenance: say unknown rather than
        // synthesizing an on-device claim.
        return "unknown"
    }

    private static func ddiLayoutValue(_ raw: String?) -> String {
        guard let raw, BridgeDDILayout(rawValue: raw) != nil else {
            return "unknown"
        }
        return raw
    }

    private static func ddiMethodValue(_ raw: String?) -> String {
        if let raw, BridgeDDIInstallMethod(rawValue: raw) != nil {
            return raw
        }
        return BridgeDDIInstallMethod.current.rawValue
    }

    private static func safeTimestamp(_ raw: String?) -> String? {
        guard let raw,
              (20...40).contains(raw.count),
              raw.first?.isNumber == true,
              raw.contains("T"),
              raw.contains("-") else { return nil }
        let allowed = Set("0123456789-:T.Z+")
        guard raw.allSatisfy({ allowed.contains($0) }) else { return nil }
        return raw
    }

    private var currentURL: URL {
        directory.appendingPathComponent(Self.currentFileName)
    }

    private var rotatedURL: URL {
        directory.appendingPathComponent(Self.rotatedFileName)
    }

    private func prepareDirectory() {
        let manager = FileManager.default
        do {
            try manager.createDirectory(at: directory, withIntermediateDirectories: true)
            if let entries = try? manager.contentsOfDirectory(atPath: directory.path) {
                for name in entries where name.contains(".stage-") {
                    try? manager.removeItem(
                        at: directory.appendingPathComponent(name)
                    )
                }
            }
            var values = URLResourceValues()
            values.isExcludedFromBackup = true
            var backupExcluded = directory
            try? backupExcluded.setResourceValues(values)
            try? manager.setAttributes([.posixPermissions: 0o700],
                                       ofItemAtPath: directory.path)
            #if os(iOS)
            try? manager.setAttributes(
                [.protectionKey: FileProtectionType.completeUntilFirstUserAuthentication],
                ofItemAtPath: directory.path
            )
            #endif
            guard manager.isWritableFile(atPath: directory.path) else {
                persistenceAvailable = false
                lastFailure = "directory-unavailable"
                return
            }
            persistenceAvailable = true
            lastFailure = nil
        } catch {
            persistenceAvailable = false
            lastFailure = "directory-unavailable"
        }
    }

    private func loadRetainedEvents() {
        guard persistenceAvailable else { return }
        guard let loadedCurrent = readEvents(from: currentURL) else {
            persistenceAvailable = false
            lastFailure = "read-failed"
            return
        }
        guard let loadedRotated = readEvents(from: rotatedURL) else {
            persistenceAvailable = false
            lastFailure = "read-failed"
            return
        }

        var seen = Set<UInt64>()
        var merged: [BridgeProductStatusEvent] = []
        for event in loadedRotated + loadedCurrent where seen.insert(event.sequence).inserted {
            merged.append(event)
        }
        merged.sort { $0.sequence < $1.sequence }

        lock.lock()
        rotated = Array(loadedRotated.suffix(maxEvents))
        current = Array(loadedCurrent.suffix(maxEvents))
        events = Array(merged.suffix(maxEvents))
        trimRAMLocked()
        sequence = merged.map(\.sequence).max() ?? 0
        lock.unlock()
    }

    /// Restores only the two validated historical mount facts from the
    /// previous process. The status file contains other display data; none of
    /// it is copied into the event schema.
    private func loadRestoredMountFacts() {
        guard let object = BridgeAtomicFile.readJSON(restoredStatusURL),
              let rawAt = object["lastOnDeviceMountAt"] as? String,
              let at = Self.safeTimestamp(rawAt) else { return }
        restoredLastOnDeviceMountAt = at
        restoredLastOnDeviceMountLayout = Self.ddiLayoutValue(
            object["lastOnDeviceMountLayout"] as? String
        )
    }

    private func appendToFilesLocked(_ event: BridgeProductStatusEvent) {
        guard let line = Self.encodedLine(event),
              !line.isEmpty,
              line.count <= maxBytes else {
            lastFailure = "encode-failed"
            return
        }
        let lineBytes = line.count
        if current.isEmpty {
            current = [event]
            return
        }
        let currentBytes = current.reduce(0) { $0 + (Self.encodedLine($1)?.count ?? 0) }
        if currentBytes + lineBytes > maxBytes || current.count >= maxEvents {
            rotated = current
            current = [event]
        } else {
            current.append(event)
        }
    }

    private func trimRAMLocked() {
        while events.count > maxEvents {
            events.removeFirst()
        }
        var bytes = events.reduce(0) { $0 + $1.formattedLine().utf8.count + 1 }
        while bytes > maxBytes, events.count > 1 {
            bytes -= events.removeFirst().formattedLine().utf8.count + 1
        }
    }

    private func retainedDatesLocked() -> [String] {
        var source = rotated + current
        if source.isEmpty {
            source = events
        }
        var dates = Set<String>()
        for event in source where event.at.count >= 10 {
            dates.insert(String(event.at.prefix(10)))
        }
        return dates.sorted()
    }

    private func flush(current: [BridgeProductStatusEvent],
                       rotated: [BridgeProductStatusEvent]) {
        var succeeded = true
        if !rotated.isEmpty {
            succeeded = writeFile(rotated, to: rotatedURL) && succeeded
        }
        succeeded = writeFile(current, to: currentURL) && succeeded
        lock.lock()
        persistenceAvailable = succeeded
        if succeeded {
            lastFailure = nil
        } else if lastFailure == nil {
            lastFailure = "write-failed"
        }
        lock.unlock()
        if !succeeded {
            BridgeLog.shared.append("status_log_write_failed")
        }
    }

    private func writeFile(_ events: [BridgeProductStatusEvent],
                           to url: URL) -> Bool {
        guard !events.isEmpty else { return true }
        var data = Data()
        for event in events {
            guard let line = Self.encodedLine(event) else { return false }
            if data.count + line.count > maxBytes { break }
            data.append(line)
        }
        guard !data.isEmpty else { return false }
        return writeAtomically(data, to: url)
    }

    private func writeAtomically(_ data: Data, to url: URL) -> Bool {
        let stage = url.deletingLastPathComponent()
            .appendingPathComponent(".\(url.lastPathComponent).stage-\(UUID().uuidString)")
        let descriptor = open(stage.path, O_WRONLY | O_CREAT | O_EXCL, 0o600)
        guard descriptor >= 0 else { return false }

        var ok = true
        data.withUnsafeBytes { raw in
            guard let base = raw.baseAddress else {
                if !raw.isEmpty { ok = false }
                return
            }
            var offset = 0
            while offset < raw.count {
                let written = write(descriptor, base.advanced(by: offset), raw.count - offset)
                if written > 0 {
                    offset += written
                } else if written < 0 && errno == EINTR {
                    continue
                } else {
                    ok = false
                    break
                }
            }
        }
        if ok { ok = fsync(descriptor) == 0 }
        close(descriptor)

        if ok {
            #if os(iOS)
            try? FileManager.default.setAttributes(
                [.protectionKey: FileProtectionType.completeUntilFirstUserAuthentication],
                ofItemAtPath: stage.path
            )
            #endif
            try? FileManager.default.setAttributes([.posixPermissions: 0o600],
                                                   ofItemAtPath: stage.path)
            ok = rename(stage.path, url.path) == 0
        }
        if !ok {
            unlink(stage.path)
        }
        return ok
    }

    private func readEvents(from url: URL) -> [BridgeProductStatusEvent]? {
        guard FileManager.default.fileExists(atPath: url.path) else { return [] }
        guard let handle = try? FileHandle(forReadingFrom: url) else { return nil }
        defer { try? handle.close() }
        let size = (try? handle.seekToEnd()) ?? 0
        let start = size > UInt64(maxBytes) ? size - UInt64(maxBytes) : 0
        do {
            try handle.seek(toOffset: start)
            guard var data = try handle.read(upToCount: maxBytes) else { return [] }
            if start > 0, let newline = data.firstIndex(of: 0x0A) {
                data = data[data.index(after: newline)...]
            }
            var decoded: [BridgeProductStatusEvent] = []
            let decoder = JSONDecoder()
            for line in data.split(separator: 0x0A) {
                if decoded.count >= maxEvents * 2 { break }
                guard line.count <= maxBytes,
                      let event = try? decoder.decode(
                        BridgeProductStatusEvent.self,
                        from: Data(line)
                      ) else { continue }
                decoded.append(event)
            }
            return decoded
        } catch {
            return nil
        }
    }

    private static func encodedLine(_ event: BridgeProductStatusEvent) -> Data? {
        let encoder = JSONEncoder()
        guard var data = try? encoder.encode(event) else { return nil }
        data.append(0x0A)
        return data
    }

    private static func bonjourValue(_ raw: String) -> String {
        switch raw {
        case "off", "starting", "published":
            return raw
        default:
            return raw.hasPrefix("failed") ? "failed" : "unknown"
        }
    }
}
